def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = [(i, j, [grid[i][j]], 1)]
    visited = {(i, j)}

    while queue:
        x, y, path, length = queue.pop()
        if length == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                queue.append((nx, ny, path + [grid[nx][ny]], length + 1))
                visited.add((nx, ny))

    return []
```

