def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    def generate_numbers(num_digits):
        if num_digits == 0:
            return [1]
        else:
            prev_numbers = generate_numbers(num_digits - 1)
            return [int(str(num) + '1') for num in prev_numbers] + \
                   [int('1' + str(num)) for num in prev_numbers]

    total_numbers = generate_numbers(n)
    return sum(1 for num in total_numbers if str(num).startswith('1') or str(num).endswith('1'))
