        elif isinstance(a, str) or isinstance(b, str):
            a = float(a) if isinstance(a, str) else float(b)
        if a > b:
            return a
        elif a < b:
            return b
        else:
            return None

    # If either input cannot be converted to float, we try to convert it to int
    except ValueError:
        try:
            # If both inputs can be converted to int, we compare them
            if isinstance(a, str) and isinstance(b, str):
                if '.' in a or '.' in b:
                    return None
                a = int(a)
                b = int(b)
            elif isinstance(a, str) or isinstance(b, str):
                a = int(a) if isinstance(a, str) else int(b)
            if a > b:
                return a
            elif a < b:
                return b
            else:
                return None

        # If either input cannot be converted to int, we leave the input as is
        except ValueError:
