    # Split the text on commas
    elif ',' in txt:
        return txt.split(',')
    else:
        # Count the number of lower-case letters with odd order in the alphabet
        count = 0
        for i, char in enumerate(txt.lower()):
            if char.islower() and i % 2!= 0:
                count += 1
        return count
