def match_parens(lst):
    '''
    Returns 'Yes' if the concatenation of the two strings in lst can form a good string, 'No' otherwise.
    A string S is considered to be good if and only if all parentheses in S are balanced.
    '''
    def is_good(s):
        stack = []
        for c in s:
            if c == '(':
                stack.append(c)
            elif c == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    return 'Yes' if is_good(lst[0]) and is_good(lst[1]) else 'No'
