def largest_smallest_integers(lst):
    """
    Create a function that returns a tuple (a, b), where 'a' is 
    the largest of negative integers, and 'b' is the smallest 
    of positive integers in a list. If there is no negative or 
    positive integers, return them as None.

    Args:
        lst (list): A list of integers

    Returns:
        tuple: A tuple containing the largest negative integer and the smallest positive integer
    """
    negative_integers = [i for i in lst if i < 0]
    positive_integers = [i for i in lst if i > 0]

    if negative_integers and positive_integers:
        return (negative_integers[-1], positive_integers[0])
    elif negative_integers:
        return (negative_integers[-1], None)
    elif positive_integers:
        return (None, positive_integers[0])
    else:
        return (None, None)
