def smallest_change(arr):
    """
    Given an array arr of integers, find the minimum number of elements that
    need to be changed to make the array palindromic.

    A palindromic array is an array that is read the same backwards and forwards.
    In one change, you can change one element to any other element.

    :param arr: List of integers
    :return: Minimum number of elements to change
    """
    def is_palindrome(arr):
        return arr == arr[::-1]

    def find_change(arr):
        if is_palindrome(arr):
            return 0
        else:
            count = 0
            for i in range(len(arr) // 2):
                if arr[i]!= arr[-i - 1]:
                    count += 1
            return count

    return find_change(arr)
