    Returns the nth Newman-Shanks-Williams prime number.

    The Newman-Shanks-Williams sequence is a sequence of prime numbers 
    where each prime number is the smallest number for which the number 
    of divisors of the number is equal to the number of prime numbers less 
    than or equal to the number.

    Args:
        n (int): The position of the prime number in the sequence.

    Returns:
        int: The nth Newman-Shanks-Williams prime number.

    Raises:
        ValueError: If n is less than 1.
    """

    if n < 1:
        raise ValueError("n must be greater than 0")

    def count_divisors(k):
        """Count the number of divisors of k."""
        count = 0
        for i in range(1, int(k ** 0.5) + 1):
            if k % i == 0:
                if k // i == i:
                    count += 1
                else:
                    count += 2
        return count

    def is_prime(k):
        """Check if k is a prime number."""
        if k < 2:
            return False
        for i in range(2, int(k ** 0.5) + 1):
            if k % i == 0:
                return False
        return True

    def newman_shanks(k):
        """Find the kth Newman-Shanks-Williams prime."""
        i = 2
        while True:
            if count_divisors(i) == k and is_prime(i):
                return i
            i += 1

    return newman_shanks(n)
