    Calculates the sum of Perrin numbers.

    Perrin numbers are a sequence of numbers that are used in combinatorial algorithms and have many interesting properties.

    The first few Perrin numbers are 2, 5, 19, 64, 211, 624, 1667, 4167, 10440, 26729.
    """

    def is_perfect(n):
        """Checks if a number is perfect."""
        factors = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                factors += 2
            if i * i == n:
                factors -= 1
        return factors == n

    def perrin(n):
        """Calculates the nth Perrin number."""
        if n == 0:
            return 0
        elif n == 1:
            return 2
        elif n == 2:
            return 5
        else:
            return perrin(n-1) + perrin(n-2) + perrin(n-3)

    def sum_perrin(n):
        """Calculates the sum of Perrin numbers up to the nth number."""
        return sum(perrin(i) for i in range(n))

    result = sum_perrin(10)  # example usage, calculate sum up to the 10th Perrin number
    return result
